app.controller("InstructorListCtrl",["$scope","$window","$http","cfpLoadingBar","$timeout","settings",function(n,t){n.search="";n.empty_list_search=!1;n.InstructorClik=function(n){t.location.href=n};n.searchText=function(){n.empty_list_search=!0;n.search=$("#search-filter").val();$("#content-instructor").hide().fadeIn("slow")};n.searchClear=function(){n.search=$("#search-filter").val("");$("#content-instructor").hide().fadeIn("slow")};n.matches=function(t){if(n.search.length<2)return n.empty_list_search=!1,!0;var r=new RegExp(n.search.toLowerCase(),"gi"),i=r.test(t.toLowerCase());return i&&(n.empty_list_search=!1),i}}]);